"% Define the open-loop transfer function L(s)
num = [9.0];
den = [1.0, 5.0, 6.0, 0.0];
sys = tf(num, den);

% Compute stability margins
% [Gm, Pm, Wcg, Wcp]
% Gm: Gain margin (absolute value)
% Pm: Phase margin (degrees)
% Wcg: Frequency where phase crossover occurs (phase = -180 deg) -> w_pc
% Wcp: Frequency where gain crossover occurs (magnitude = 0 dB) -> w_gc
[Gm, Pm, Wcg, Wcp] = margin(sys);

% Convert Gain Margin to decibels
Gm_dB = 20 * log10(Gm);

% Populate results structure according to required keys
results = struct();
results.gm_db = Gm_dB;
results.pm_deg = Pm;
results.w_gc = Wcp;  % Gain crossover frequency
results.w_pc = Wcg;  % Phase crossover frequency

% Write results to result.json
fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonencode(results));
fclose(fid);"
